dir$s22.prototype.beforeButtonDialogClick = function (id) {
var p = this._dir, g = p.grid(0), dt = g.data;
  	var d = p.valForm('ngay_hl'),d1 = p.valForm('ngay_hld');
	var e = $.date(d,"dd/mm/yy"),e1 = $.date(d1,"dd/mm/yy");
  switch (id) {
    case 'ok':
		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
			$.alert(p.msg('ErrDay')+' ' +'('+ e + ' phải lớn hơn ' + e1+')');
			return false;
			Break;
			}
    default:
      break;
  }
  return true;
}
dir$s22.prototype.beforeButtonGridClick = function (id, gindex) {
var p = this._dir;
  switch (id) {
    case 'refresh':
      dir$s22LoadFieldGrid(p, 0);
      return false;
    default:
      break;
  }
  return true;
}
